-- Code generated by togo. PostgreSQL schema fragment (converted from togo 0.2.31's SQLite-only template) — hand-editable; desired state for atlas migrate diff.
CREATE TABLE servers (
    id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
    team_id text NOT NULL,
    name text NOT NULL,
    provider text NOT NULL,
    kind text NOT NULL,
    status text NOT NULL,
    credential_id text,
    provider_ref text,
    hostname text,
    ip_address text,
    os text,
    os_version text,
    arch text,
    kernel text,
    agent_version text,
    agent_public_key text,
    ssh_public_key text,
    ssh_private_key_sealed text,
    facts jsonb,
    checks jsonb,
    metrics jsonb,
    github jsonb,
    color text,
    icon text,
    logo_url text,
    spec jsonb,
    error text,
    created_by text NOT NULL,
    last_seen_at timestamptz,
    enrolled_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

-- Hosbah: a server belongs to one team. status is its lifecycle; "online" is derived from
-- last_seen_at (heartbeats), so a control-plane crash never leaves a stale "online" flag behind.
-- agent_public_key is the ed25519 key the agent generated at enrolment; it signs every auth
-- challenge. ssh_private_key_sealed is the per-server bootstrap key, sealed with the team DEK.
ALTER TABLE servers ADD CONSTRAINT servers_provider_check CHECK (provider IN ('byo', 'proxmox'));
ALTER TABLE servers ADD CONSTRAINT servers_kind_check CHECK (kind IN ('byo', 'vm', 'lxc'));
ALTER TABLE servers ADD CONSTRAINT servers_status_check CHECK (status IN ('pending', 'provisioning', 'enrolled', 'failed'));
CREATE UNIQUE INDEX servers_team_name_key ON servers (team_id, name);
CREATE UNIQUE INDEX servers_id_team_key ON servers (id, team_id);
CREATE INDEX servers_team_idx ON servers (team_id, created_at);

-- github: what the server's GitHub CLI (gh) connection last reported — {installed, version,
-- connected, user, scopes, checked_at} and, while a device login waits for a human, pending
-- {operation, user_code, verification_uri, expires_at}. Written from github.* operation results
-- (agent scope); never a token (gh keeps its login on the server, in /etc/hosbah/gh).

-- color / icon / logo_url: how the team styles the server (home page cards and elsewhere). color is
-- #RRGGBB; icon is a key from the allowlist in internal/provisioning/appearance.go; logo_url is an
-- https image shown instead of the icon. NULL is the default look.
ALTER TABLE servers ADD CONSTRAINT servers_color_check CHECK (color IS NULL OR color ~ '^#[0-9A-Fa-f]{6}$');
ALTER TABLE servers ADD CONSTRAINT servers_icon_check CHECK (icon IS NULL OR icon IN ('server', 'database', 'globe', 'cloud', 'cpu', 'box', 'rocket', 'shield', 'code', 'terminal', 'layers', 'zap', 'flame', 'leaf', 'star', 'heart', 'briefcase', 'home', 'store', 'graduation-cap', 'building', 'gamepad', 'music', 'camera'));
ALTER TABLE servers ADD CONSTRAINT servers_logo_url_check CHECK (logo_url IS NULL OR (logo_url LIKE 'https://%' AND length(logo_url) <= 500));
